 const labels={'work.saved':["作品版本保存","完成"],'work.completed':["隔离JavaScript实作","完成"],'work.failed':["隔离JavaScript实作","未完成"],'work.cancelled':["隔离JavaScript实作","已取消"],'work.timed_out':["隔离JavaScript实作","已停止"],'work.interrupted':["隔离JavaScript实作","重启中断"],'document.read':["文档阅读","完成"],'memory.searched':["自己的记忆搜索","完成"],'record.read':["原始纪录阅读","完成"],'tool.note.result':["受控笔记","完成"],'consult.result':["独立模型请教","完成"],'consult.failed':["独立模型请教","未完成"],'tool.owner_reply':["回复 Owner","完成"],'tool.owner_message':["主动传讯给 Owner","已保存；不代表已读"],'tool.web.result':["外网工作","已回报结果"],'tool.web.failed':["外网工作","未完成"],'tool.denied':["工具使用","遭拒绝"],'cycle.committed':["模型活动","完成"],'cycle.incomplete':["模型活动","未确认完成"]};
 for(const e of own){const label=labels[e.type];if(label)work.push({title:label[0],state:label[1],at:e.utc,evidence:e});if(e.type==='tool.note.result')outputs.push({kind:'note',title:e.result.name,text:e.result.text,at:e.utc,evidence:e});}
