 function renderPreview(h){preview.onload=()=>{const doc=preview.contentDocument;if(!doc)return;const css=doc.createElement('style');css.textContent=h.css;doc.head.append(css);for(const update of h.updates){const n=doc.querySelector('[data-hub-node="'+update.node+'"]');if(n)n.textContent=update.text;}for(const n of doc.querySelectorAll('button,input[type=button]'))n.onclick=()=>run(async()=>{const inputs=[...doc.querySelectorAll('input,textarea,select')].map(i=>({node:i.dataset.hubNode,value:i.value,checked:i.checked}));previewEvents.push({node:n.dataset.hubNode,inputs});const next=await post('preview-event',{id:previewProject.id,version:previewProject.version,events:previewEvents});renderPreview(next);});};preview.srcdoc='<meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\';script-src \'none\';style-src \'unsafe-inline\';img-src data:;form-action \'none\';base-uri \'none\'">'+h.html;}
